const $=s=>document.querySelector(s),app=$('#app');
const api=async(path,opt={})=>{const r=await fetch(path,{headers:{'Content-Type':'application/json'},...opt});if(r.status===204)return;let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'请求失败');return d};
let me,domains=[],credentials=[],active,records=[],types=['A','CNAME','AAAA'],notificationDuration=5,showFiltered=false,publicPolicy={},dnsSearch='',domainSearch='',httpsSearch='',userSearch='';
let currentView='';function updateHeaderSearch(){}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const notice=(s,bad=false)=>{const n=$('#notice');if(n){n.textContent=s;n.className=bad?'error':'ok'}};
function flash(message,bad=false,actions=[]){let box=$('#flash-stack');if(!box){box=document.createElement('div');box.id='flash-stack';document.body.appendChild(box)}const item=document.createElement('div');item.className='flash '+(bad?'flash-error':'flash-success');item.innerHTML=`<span>${esc(message)}</span><div class="flash-actions"></div><button class="flash-close" aria-label="关闭">×</button>`;const actionBox=item.querySelector('.flash-actions');actions.forEach(a=>{const b=document.createElement('button');b.textContent=a.label;b.className=a.primary?'':'ghost';b.onclick=()=>{item.remove();a.run()};actionBox.appendChild(b)});item.querySelector('.flash-close').onclick=()=>item.remove();box.appendChild(item);if(!actions.length&&notificationDuration!=='manual'){setTimeout(()=>item.remove(),Number(notificationDuration||5)*1000)}}
function ask(message,run){flash(message,false,[{label:'确认',primary:true,run},{label:'取消',run:()=>{}}])}
function login(){app.innerHTML=`<main class="login"><form id="login"><span class="eyebrow">Welcome back</span><h1>DNS Panel</h1><p>统一管理你的 DNS 记录</p><label>用户名<input name="username" autocomplete="username" required autofocus></label><label>密码<input name="password" type="password" autocomplete="current-password" required></label><div id="notice"></div><button>登录</button><button id="forgotPassword" type="button" class="form-link">忘记密码</button>${publicPolicy.registrationEnabled?'<button id="openRegister" type="button" class="form-link">创建新账号</button>':''}</form></main>`;$('#login').onsubmit=async e=>{e.preventDefault();try{await api('/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});boot(true)}catch(x){notice(x.message,true)}};$('#forgotPassword').onclick=forgotPasswordView;if($('#openRegister'))$('#openRegister').onclick=registerView}
function forgotPasswordView(){app.innerHTML=`<main class="login"><form id="forgot"><span class="eyebrow">Recovery</span><h1>找回密码</h1><p>输入注册邮箱，我们会发送用户名和一次性重置链接。</p><label>邮箱<input name="email" type="email" required autofocus></label><div id="notice"></div><button>发送重置邮件</button><button id="backLogin" type="button" class="form-link">返回登录</button></form></main>`;$('#backLogin').onclick=login;$('#forgot').onsubmit=async e=>{e.preventDefault();try{await api('/api/password/forgot',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});notice('如果邮箱存在，重置邮件已经发送')}catch(x){notice(x.message,true)}}}
function resetPasswordView(token){app.innerHTML=`<main class="login"><form id="reset"><span class="eyebrow">Recovery</span><h1>重置密码</h1><label>新密码<input name="password" type="password" required></label><label>再次输入<input name="confirmPassword" type="password" required></label><div id="notice"></div><button>重置密码</button></form></main>`;$('#reset').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));v.token=token;try{await api('/api/password/reset',{method:'POST',body:JSON.stringify(v)});history.replaceState({},'',location.pathname);login();flash('密码已经重置，请登录')}catch(x){notice(x.message,true)}}}
async function registerView(){const hint=await passwordPolicy();app.innerHTML=`<main class="login"><form id="register"><span class="eyebrow">Create account</span><h1>注册</h1><p>填写信息后，我们会向你的邮箱发送验证码；验证成功后才会完成注册。</p><label>用户名<input name="username" required autofocus></label><label>邮箱<input name="email" type="email" required></label><label>密码<input name="password" type="password" required><small>${hint}</small></label><div id="notice"></div><button>发送验证码</button><button id="backLogin" type="button" class="form-link">返回登录</button></form></main>`;$('#backLogin').onclick=login;$('#register').onsubmit=async e=>{e.preventDefault();try{const result=await api('/api/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});registrationVerificationView(result.email)}catch(x){notice(x.message,true)}}}
function registrationVerificationView(email){app.innerHTML=`<main class="login"><form id="registerVerify"><span class="eyebrow">Email verification</span><h1>验证邮箱</h1><p>验证码已发送至 ${esc(email)}，10 分钟内有效。</p><label>6 位验证码<input name="code" inputmode="numeric" maxlength="6" required autofocus></label><div id="notice"></div><button>完成验证</button></form></main>`;$('#registerVerify').onsubmit=async e=>{e.preventDefault();try{await api('/api/register/verify',{method:'POST',body:JSON.stringify({email,code:new FormData(e.target).get('code')})});login();flash('邮箱验证成功，请登录')}catch(x){notice(x.message,true)}}}
async function passwordPolicy(){const p=await api('/api/policy'),r=[];if(p.minLength>0)r.push(`长度至少 ${p.minLength} 位`);if(p.number)r.push('数字');if(p.uppercase)r.push('大写字母');if(p.lowercase)r.push('小写字母');if(p.symbol)r.push('符号');return r.length?'密码要求：'+r.join('、'):'当前未启用密码长度或复杂度要求'}
async function firstLogin(){const hint=await passwordPolicy();app.innerHTML=`<main class="login"><form id="first"><h2>首次登录安全设置</h2><p>请修改默认账号、密码并填写登录邮箱。</p><label>新用户名<input name="username" required></label><label>登录邮箱<input name="email" type="email" required></label><label>新密码<input name="newPassword" type="password" required><small>${hint}</small></label><label>再次输入新密码<input name="confirmPassword" type="password" required></label><div id="notice"></div><button>保存并继续</button></form></main>`;$('#first').onsubmit=async e=>{e.preventDefault();try{await api('/api/me/password',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});boot(true)}catch(x){notice(x.message,true)}}}
async function boot(refreshOnLogin=false){publicPolicy=await api('/api/policy');notificationDuration=publicPolicy.notificationDuration||'5';if(Array.isArray(publicPolicy.defaultRecordTypes))types=publicPolicy.defaultRecordTypes;try{me=await api('/api/me')}catch{return login()}if(me.mustChangePassword)return firstLogin();if(me.mfaRequired)return mfaView();[domains,credentials]=await Promise.all([api('/api/domains'),api('/api/credentials')]);let refreshResult;if(refreshOnLogin){try{refreshResult=await api('/api/domains/refresh',{method:'POST'})}catch(e){refreshResult={error:e.message}}}render();if(refreshResult?.error)flash('登录成功，但 DNS 自动最新化失败：'+refreshResult.error,true);else if(refreshResult)flash(`登录成功，已从 Cloudflare 最新化 ${refreshResult.refreshed} 个域名`)}
function mfaView(){const methods=me.mfaMethods||[];app.innerHTML=`<main class="login"><form id="mfa"><span class="eyebrow">Second factor</span><h1>二次认证</h1><p>请选择一种方式完成登录验证。</p><div class="mfa-methods">${methods.includes('otp')?'<button type="button" data-mfa="otp">OTP 验证器</button>':''}${methods.includes('passkey')?'<button type="button" data-mfa="passkey">Passkey</button>':''}${methods.includes('email')?'<button type="button" data-mfa="email">邮箱验证码</button>':''}</div><div id="mfaInput"></div><div id="notice"></div><button id="mfaLogout" type="button" class="form-link">退出登录</button></form></main>`;$('#mfaLogout').onclick=async()=>{await api('/api/logout',{method:'POST'});login()};document.querySelectorAll('[data-mfa]').forEach(x=>x.onclick=()=>startMFA(x.dataset.mfa))}
async function startMFA(method){if(method==='passkey')return loginWithPasskey();if(method==='email'){try{await api('/api/me/mfa/email',{method:'POST'});flash('邮箱验证码已发送')}catch(e){flash(e.message,true);return}}$('#mfaInput').innerHTML=`<label>${method==='otp'?'OTP 动态码':'邮箱验证码'}<input id="mfaCode" inputmode="numeric" maxlength="6" required autofocus></label><button id="verifyMFA" type="button">验证并登录</button>`;$('#verifyMFA').onclick=async()=>{try{await api(`/api/me/mfa/${method==='otp'?'otp':'email/verify'}`,{method:'POST',body:JSON.stringify({code:$('#mfaCode').value})});boot(true)}catch(e){notice(e.message,true)}}}
async function loginWithPasskey(){try{const start=await api('/api/me/mfa/passkey/begin',{method:'POST'}),options=start.options.publicKey;options.challenge=fromB64(options.challenge);if(options.allowCredentials)options.allowCredentials.forEach(x=>x.id=fromB64(x.id));const credential=await navigator.credentials.get({publicKey:options}),body={id:credential.id,rawId:toB64(credential.rawId),type:credential.type,response:{clientDataJSON:toB64(credential.response.clientDataJSON),authenticatorData:toB64(credential.response.authenticatorData),signature:toB64(credential.response.signature),userHandle:credential.response.userHandle?toB64(credential.response.userHandle):null},clientExtensionResults:credential.getClientExtensionResults(),authenticatorAttachment:credential.authenticatorAttachment};await api('/api/me/mfa/passkey/finish?token='+encodeURIComponent(start.sessionToken),{method:'POST',body:JSON.stringify(body)});boot(true)}catch(e){flash('Passkey 验证失败：'+e.message,true)}}
function render(){app.innerHTML=`<header><strong>DNS Panel</strong><button class="nav on" data-view="dns">DNS 管理</button><button class="nav" data-view="https">HTTPS 监控</button><button class="nav" data-view="domains">域名管理</button><button class="nav" data-view="keys">API Key</button>${me.role==='admin'?'<button class="nav" data-view="users">用户管理</button><button class="nav" data-view="settings">全局设置</button>':''}<button id="account" class="ghost">${esc(me.username)}</button><button id="logout" class="ghost">退出</button></header><div id="page"></div>`;$('#account').onclick=profileView;$('#logout').onclick=async()=>{await api('/api/logout',{method:'POST'});login()};document.querySelectorAll('.nav').forEach(x=>x.onclick=()=>show(x.dataset.view));show('dns')}
function show(v){if((v==='users'||v==='settings')&&me.role!=='admin'){v='dns';flash('该功能仅限管理员使用',true)}document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('on',x.dataset.view===v));if(v==='dns')dnsView();if(v==='https')httpsMonitorView();if(v==='domains')domainManagementView();if(v==='keys')keyView();if(v==='users')userManagementView();if(v==='settings')settingsView()}
function dnsView(){const page=$('#page');page.innerHTML=`<div class="layout"><aside><div class="aside-title"><h3>DNS 管理</h3><span>${domains.length}</span></div><button id="refreshAll" class="refresh-button">↻ 最新化所有域名</button>${domains.map(d=>`<button class="domain ${active?.id===d.id?'on':''}" data-id="${d.id}"><b>${esc(d.name)}</b><small><i class="provider-dot ${esc(d.provider)}"></i>${esc(d.provider)} · ${esc(d.credential)}</small></button>`).join('')}</aside><main id="content"></main></div>`;document.querySelectorAll('.domain').forEach(x=>x.onclick=()=>{active=domains.find(d=>d.id==x.dataset.id);loadRecords()});$('#refreshAll').onclick=()=>ask('最新化会以云端记录覆盖所有域名尚未同步的本地修改，是否继续？',refreshAllDomains);if(active)domainContent();else $('#content').innerHTML='<div class="empty"><div class="empty-icon">◎</div><b>还没有选择域名</b><span>请先在“域名管理”中添加并选择域名</span></div>'}
async function refreshAllDomains(){flash('正在从云端最新化所有域名…');try{const x=await api('/api/domains/refresh',{method:'POST'});if(active){records=await api(`/api/domains/${active.id}/records`);dnsView()}flash(`最新化成功，共读取 ${x.refreshed} 个 Cloudflare 域名`)}catch(e){flash('最新化失败：'+e.message,true)}}
async function loadRecords(){try{records=await api(`/api/domains/${active.id}/records`);dnsView()}catch(e){flash(e.message,true)}}
function domainContent(){const c=$('#content');c.innerHTML=`<div class="title"><div><span class="eyebrow">${esc(active.provider)} · ${esc(active.credential)}</span><div class="domain-heading"><h1>${esc(active.name)}</h1><span id="recordCount" class="record-count"></span></div></div><button id="addRecord" class="secondary">＋ 新增记录</button><button id="saveSync">保存并同步</button></div><div class="sync-result" id="syncResult">修改会先安全保存到 SQLite，再同步到对应云厂商。</div><label class="table-search"><span>检索 DNS 记录</span><input id="dnsSearch" type="search" value="${esc(dnsSearch)}" placeholder="输入名称、记录值、类型或备注"></label><div class="checks">${['A','CNAME','AAAA','CAA','TXT','MX','SRV'].map(t=>`<label><input data-type type="checkbox" value="${t}" ${types.includes(t)?'checked':''}>${t}</label>`).join('')}<label class="filter-toggle"><input id="showFiltered" type="checkbox" ${showFiltered?'checked':''}>显示已过滤记录</label></div><div class="table"><div class="tr head"><span>类型</span><span>名称</span><span>记录值</span><span>TTL</span><span>优先级</span><span>备注</span><span>小黄云</span><span></span></div><div id="recordRows"></div></div>`;drawRows();$('#dnsSearch').oninput=e=>{dnsSearch=e.target.value;drawRows()};document.querySelectorAll('.checks input[data-type]').forEach(x=>x.onchange=()=>{types=[...document.querySelectorAll('.checks input[data-type]:checked')].map(i=>i.value);drawRows()});$('#showFiltered').onchange=e=>{showFiltered=e.target.checked;drawRows()};$('#addRecord').onclick=()=>{records.push({id:0,type:'A',name:'@',content:'',ttl:300,priority:null,comment:'',proxied:false,status:'created'});drawRows()};$('#saveSync').onclick=saveAndSync}
function filterTerms(value){return String(value||'').split(/\r?\n/).map(x=>x.trim().toLowerCase()).filter(Boolean)}
function isFiltered(r){const name=String(r.name||'').toLowerCase(),content=String(r.content||'').toLowerCase();return filterTerms(me.nameFilter).some(x=>name.includes(x))||filterTerms(me.valueFilter).some(x=>content.includes(x))}
function drawRows(){const query=dnsSearch.trim().toLowerCase(),fullName=r=>{const name=String(r.name||'').replace(/\.$/,'');if(name===''||name==='@')return active?.name||'';const zone=String(active?.name||'').replace(/\.$/,'');return name.toLowerCase()===zone.toLowerCase()||name.toLowerCase().endsWith('.'+zone.toLowerCase())?name:`${name}.${zone}`},matches=r=>[r.type,r.name,fullName(r),r.content,r.ttl,r.priority,r.comment,r.proxied?'已启用代理':''].join(' ').toLowerCase().includes(query),visible=r=>!r.deleted&&(query?matches(r):(types.includes(r.type)&&(!isFiltered(r)||showFiltered)));$('#recordRows').innerHTML=records.map((r,i)=>visible(r)?`<div class="tr ${isFiltered(r)?'filtered-record':''}" data-filtered="${isFiltered(r)}" data-i="${i}"><select data-k="type">${['A','AAAA','CNAME','TXT','MX','CAA','SRV'].map(t=>`<option ${r.type===t?'selected':''}>${t}</option>`).join('')}</select><input data-k="name" value="${esc(r.name)}"><input data-k="content" value="${esc(r.content)}"><input data-k="ttl" type="number" min="1" value="${r.ttl}"><input data-k="priority" type="number" value="${r.priority??''}"><input data-k="comment" value="${esc(r.comment)}" placeholder="备注"><label class="proxy">${['A','AAAA','CNAME'].includes(r.type)?`<input data-k="proxied" type="checkbox" ${r.proxied?'checked':''}><span>启用</span>`:'—'}</label><button class="danger" data-del="${i}">删除</button></div>`:'').join('');const total=records.filter(r=>!r.deleted).length,shown=records.filter(visible).length,count=$('#recordCount');if(count)count.textContent=query?`检索到 ${shown} / ${total} 条记录`:(shown===total?`共 ${total} 条记录`:`共 ${total} 条 · 当前显示 ${shown} 条`);document.querySelectorAll('.tr[data-i] input,.tr[data-i] select').forEach(x=>x.oninput=()=>{const r=records[x.closest('.tr').dataset.i],k=x.dataset.k;r[k]=x.type==='checkbox'?x.checked:k==='ttl'?Number(x.value):k==='priority'?(x.value===''?null:Number(x.value)):x.value;if(k==='type')drawRows()});document.querySelectorAll('[data-del]').forEach(x=>x.onclick=()=>{records[x.dataset.del].deleted=true;drawRows()})}
async function saveAndSync(){const button=$('#saveSync'),result=$('#syncResult');button.disabled=true;result.className='sync-result busy';result.textContent='正在保存并同步…';try{await api(`/api/domains/${active.id}/records`,{method:'PUT',body:JSON.stringify(records)});const x=await api(`/api/domains/${active.id}/sync`,{method:'POST'});result.className='sync-result ok';result.textContent=`同步成功，共处理 ${x.synced} 项变更。`;flash(result.textContent);records=await api(`/api/domains/${active.id}/records`);drawRows()}catch(e){result.className='sync-result error';result.textContent='同步失败：'+e.message;flash(result.textContent,true)}finally{button.disabled=false}}
function domainManagementView(){const p=$('#page');p.innerHTML=`<main><div class="page-heading"><div><span class="eyebrow">配置中心</span><h1>域名管理</h1><p class="hint">指定需要管理的域名和 API Key。每次登录后会自动从云端读取记录并写入 SQLite。</p></div></div>${credentials.length?`<form id="domainForm" class="domain-form"><label>域名<input name="name" placeholder="example.com" required></label><label>API Key<select name="credentialId">${credentials.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.provider)}</option>`).join('')}</select></label><label>Zone ID（可选）<input name="zoneId" placeholder="Cloudflare 可自动查询"></label><div id="notice"></div><button>＋ 新增域名</button></form>`:'<div class="error">请先在 API Key 页面添加凭据。</div>'}<div class="domain-table"><div class="domain-row head"><span>域名</span><span>厂商</span><span>API Key</span><span>Zone ID</span><span>拖拽排序</span><span></span></div>${domains.map((d,i)=>`<div class="domain-row" data-domain-drag="${d.id}" draggable="true"><b>${esc(d.name)}</b><span class="provider-pill">${esc(d.provider)}</span><span>${esc(d.credential)}</span><code>${esc(d.zoneId||'自动查询')}</code><div class="managed-drag-handle">⠿ 拖动</div><button class="danger" data-domain="${d.id}">删除</button></div>`).join('')}</div></main>`;const form=$('#domainForm');if(form)form.onsubmit=async e=>{e.preventDefault();const value=Object.fromEntries(new FormData(form)),credential=credentials.find(x=>x.id==value.credentialId);value.credentialId=Number(value.credentialId);value.provider=credential.provider;try{await api('/api/domains',{method:'POST',body:JSON.stringify(value)});active=undefined;await boot();show('domains');flash('域名已添加')}catch(x){notice(x.message,true)}};bindManagedDrag('[data-domain-drag]','domains',domains,'domains');document.querySelectorAll('[data-domain]').forEach(x=>x.onclick=()=>ask('确定删除该域名及其本地 DNS 记录？此操作不会删除云端记录。',async()=>{try{await api('/api/domains/'+x.dataset.domain,{method:'DELETE'});if(active?.id==x.dataset.domain)active=undefined;await boot();show('domains');flash('域名本地配置已删除')}catch(e){flash(e.message,true)}}))}
function keyView(){const p=$('#page');p.innerHTML=`<main><div class="page-heading"><div><span class="eyebrow">凭据中心</span><h1>API Key 管理</h1><p class="hint">敏感字段保存后不会回传浏览器。Cloudflare Token 至少需要 Zone Read、DNS Read 和 DNS Write 权限。</p></div></div><form id="keyForm" class="inline-form"><label>别名<input name="name" placeholder="例如：主账号" required></label><label>厂商<select name="provider"><option value="cloudflare">Cloudflare</option><option value="aliyun">阿里云</option><option value="tencent">腾讯云</option></select></label><label id="keyField"><span>API Token</span><input name="accessKey" type="password" autocomplete="off" required></label><label id="secretField" hidden><span>Secret / Token</span><input name="secret" type="password" autocomplete="off"></label><div id="notice"></div><button>＋ 新增 API Key</button></form><div class="credential-table"><div class="credential-row head"><span>别名</span><span>厂商</span><span>Key</span><span>创建时间</span><span>拖拽排序</span><span></span></div>${credentials.map((x,i)=>`<div class="credential-row" data-key-drag="${x.id}" draggable="true"><b>${esc(x.name)}</b><span class="provider-pill">${esc(x.provider)}</span><code>${esc(x.accessKey)}</code><span>${esc(x.createdAt)}</span><div class="managed-drag-handle">⠿ 拖动</div><button class="danger" data-key="${x.id}">删除</button></div>`).join('')}</div></main>`;const form=$('#keyForm'),provider=form.elements.provider,keyLabel=$('#keyField span'),secret=$('#secretField');const updateFields=()=>{const cloudflare=provider.value==='cloudflare';keyLabel.textContent=cloudflare?'API Token':'Access Key / Secret ID';secret.hidden=cloudflare;form.elements.secret.required=!cloudflare};provider.onchange=updateFields;updateFields();form.onsubmit=async e=>{e.preventDefault();const value=Object.fromEntries(new FormData(form));value.extra={};try{await api('/api/credentials',{method:'POST',body:JSON.stringify(value)});await boot();show('keys');flash('API Key 已添加')}catch(x){notice(x.message,true)}};bindManagedDrag('[data-key-drag]','credentials',credentials,'keys');document.querySelectorAll('[data-key]').forEach(x=>x.onclick=()=>ask('确定删除？关联域名将失去凭据。',async()=>{try{await api('/api/credentials/'+x.dataset.key,{method:'DELETE'});await boot();show('keys');flash('API Key 已删除')}catch(e){flash(e.message,true)}}))}
async function moveManagedItem(endpoint,list,index,direction,view){const target=index+direction;if(target<0||target>=list.length)return;[list[index],list[target]]=[list[target],list[index]];try{await api(`/api/${endpoint}/order`,{method:'PUT',body:JSON.stringify({ids:list.map(x=>x.id)})});show(view);flash('顺序已保存')}catch(e){[list[index],list[target]]=[list[target],list[index]];show(view);flash('顺序保存失败：'+e.message,true)}}
function bindManagedDrag(selector,endpoint,list,view){document.querySelectorAll(selector).forEach(row=>{row.ondragstart=e=>{e.dataTransfer.setData('text/plain',row.dataset.domainDrag||row.dataset.keyDrag);row.classList.add('dragging')};row.ondragend=()=>row.classList.remove('dragging');row.ondragover=e=>{e.preventDefault();row.classList.add('drag-over')};row.ondragleave=()=>row.classList.remove('drag-over');row.ondrop=async e=>{e.preventDefault();row.classList.remove('drag-over');const source=Number(e.dataTransfer.getData('text/plain')),target=Number(row.dataset.domainDrag||row.dataset.keyDrag);if(source===target)return;const snapshot=[...list],from=list.findIndex(x=>x.id===source),to=list.findIndex(x=>x.id===target),moved=list.splice(from,1)[0];list.splice(to,0,moved);show(view);try{await api(`/api/${endpoint}/order`,{method:'PUT',body:JSON.stringify({ids:list.map(x=>x.id)})});flash('拖拽顺序已保存')}catch(err){list.splice(0,list.length,...snapshot);show(view);flash(err.message,true)}}})}
async function userManagementView(page=1){const data=await api(`/api/admin/users?page=${page}&per_page=50&q=${encodeURIComponent(userSearch.trim())}`),pages=Math.max(1,Math.ceil(data.total/data.perPage));$('#page').innerHTML=`<main><div class="page-heading"><div><span class="eyebrow">Administration</span><h1>用户管理</h1><p class="hint">${userSearch?`检索到 ${data.total} 个用户`:`共 ${data.total} 个用户`}，每页最多 50 个。</p></div></div><div class="user-table"><div class="user-row head"><span>用户名</span><span>邮箱</span><span>角色</span><span>OTP</span><span>Passkey</span><span></span></div>${data.items.map(x=>`<div class="user-row"><b>${esc(x.username)}</b><span>${esc(x.email)}</span><span class="provider-pill">${esc(x.role)}</span><span>${x.otpCount} 个</span><span>${x.passkeyCount} 个</span><button class="danger" data-user-reset="${x.id}" ${x.email?'':'disabled'}>发送重置链接</button></div>`).join('')}</div><div class="pagination"><button id="prevPage" ${page<=1?'disabled':''}>上一页</button><span>${page} / ${pages}</span><button id="nextPage" ${page>=pages?'disabled':''}>下一页</button></div></main>`;$('#prevPage').onclick=()=>userManagementView(page-1);$('#nextPage').onclick=()=>userManagementView(page+1);document.querySelectorAll('[data-user-reset]').forEach(x=>x.onclick=()=>ask('将向该用户邮箱发送一小时内有效的一次性密码重置链接，是否继续？',async()=>{try{await api(`/api/admin/users/${x.dataset.userReset}/reset-password`,{method:'POST'});flash('密码重置链接已发送')}catch(e){flash(e.message,true)}}))}
let showHiddenMonitors=false,showHTTPSDomainExclusions=false,httpsExcludedDomainIDs=[];
async function httpsMonitorView(){const [items,excluded]=await Promise.all([api('/api/https-monitors'),api('/api/https-monitors/excluded-domains')]);httpsExcludedDomainIDs=excluded;renderHTTPSMonitors(items)}
function renderHTTPSMonitors(items){const priority=x=>!x.lastChecked?3:!x.valid?0:x.daysRemaining<=15?1:2,visible=items.filter(x=>showHiddenMonitors||!x.hidden).map((x,index)=>({x,index})).sort((a,b)=>priority(a.x)-priority(b.x)||((a.x.valid&&b.x.valid)?a.x.daysRemaining-b.x.daysRemaining:0)||a.index-b.index).map(entry=>entry.x),status=x=>!x.lastChecked?['','尚未检测']:x.valid?[x.daysRemaining<=15?'warning':'valid',`有效至 ${new Date(x.notAfter).toLocaleDateString()}（剩余 ${x.daysRemaining} 天）`]:x.notAfter&&new Date(x.notAfter)<new Date()?['invalid',`证书域名 ${x.certificateDomains||'尚未记录（请重新检测）'} 已过期 ${Math.max(1,Math.ceil((Date.now()-new Date(x.notAfter).getTime())/86400000))} 天`]:['invalid',`失败：${x.error}`];$('#page').innerHTML=`<main><div class="page-heading"><div><span class="eyebrow">Availability & TLS</span><h1>HTTPS 监控</h1><p class="hint">自动汇总所有域名的 A、AAAA 和 CNAME 记录；按证书风险和剩余有效期自动排列，屏蔽项不会检测或告警。</p></div><button id="checkHTTPS">立即检测未屏蔽项</button></div><div class="monitor-toolbar"><label class="monitor-hidden-toggle"><input id="showHiddenMonitors" type="checkbox" ${showHiddenMonitors?'checked':''}>显示所有屏蔽项</label><div><span class="monitor-count">当前显示 <b>${visible.length}</b> 条记录</span><button id="manageHTTPSExclusions" type="button" class="secondary">${showHTTPSDomainExclusions?'收起域名排除':'管理域名排除'}</button></div></div>${showHTTPSDomainExclusions?`<section class="https-exclusion-panel"><div><h3>排除不提供 HTTPS 的域名</h3><p class="hint">选中后，该域名下的全部 A、AAAA、CNAME 记录都不会检测或告警。</p></div><div class="exclusion-domain-list">${domains.map(d=>`<label><input type="checkbox" data-https-domain-exclusion value="${d.id}" ${httpsExcludedDomainIDs.includes(d.id)?'checked':''}>${esc(d.name)}</label>`).join('')||'<span class="empty-note">暂无可选域名</span>'}</div><button id="saveHTTPSExclusions" type="button">保存域名排除</button></section>`:''}<div class="monitor-table"><div class="monitor-row head"><span>主机</span><span>端口</span><span>备注</span><span>证书状态</span><span>上次检查</span><span>操作</span><span>屏蔽</span></div>${visible.map(x=>{const s=status(x);return `<div class="monitor-row ${x.hidden?'monitor-hidden':''}" data-monitor="${x.id}"><b>${esc(x.host)}</b><input data-monitor-port type="number" min="1" max="65535" value="${x.port}"><input data-monitor-note value="${esc(x.note)}" placeholder="备注"><span class="monitor-status ${s[0]}" data-status="${x.id}" title="${x.lastChecked?esc(`类型：${x.type} / 记录：${x.value}`):''}">${s[1]}</span><span class="last-checked" data-checked="${x.id}">${x.lastChecked?new Date(x.lastChecked).toLocaleString():'—'}</span><button data-monitor-check type="button" ${x.hidden?'disabled':''}>监控</button><input data-monitor-hidden type="checkbox" ${x.hidden?'checked':''} ${x.filtered||x.domainExcluded?`disabled title="${x.domainExcluded?'由 HTTPS 域名排除规则屏蔽':'由个人过滤规则屏蔽'}"`:''}></div>`}).join('')||'<div class="empty-note">没有可监控的 A、AAAA 或 CNAME 记录</div>'}</div></main>`;$('#showHiddenMonitors').onchange=e=>{showHiddenMonitors=e.target.checked;renderHTTPSMonitors(items)};$('#manageHTTPSExclusions').onclick=()=>{showHTTPSDomainExclusions=!showHTTPSDomainExclusions;renderHTTPSMonitors(items)};const saveExclusions=$('#saveHTTPSExclusions');if(saveExclusions)saveExclusions.onclick=async()=>{const ids=[...document.querySelectorAll('[data-https-domain-exclusion]:checked')].map(x=>Number(x.value));saveExclusions.disabled=true;try{await api('/api/https-monitors/excluded-domains',{method:'PUT',body:JSON.stringify({ids})});httpsExcludedDomainIDs=ids;await httpsMonitorView();flash('HTTPS 域名排除已保存')}catch(e){flash(e.message,true);saveExclusions.disabled=false}};$('#checkHTTPS').onclick=async()=>{flash('正在检测未屏蔽的 HTTPS 和证书…');try{const results=await api('/api/https-monitors/check',{method:'POST'});results.forEach(x=>{const old=items.find(y=>y.id===x.id);if(old)Object.assign(old,x);const n=document.querySelector(`[data-status="${x.id}"]`),t=document.querySelector(`[data-checked="${x.id}"]`),s=status(x);if(n){n.className='monitor-status '+s[0];n.textContent=s[1];n.title=x.lastChecked?`类型：${x.type} / 记录：${x.value}`:''}if(t)t.textContent=x.lastChecked?new Date(x.lastChecked).toLocaleString():'—'});renderHTTPSMonitors(items);flash('HTTPS 检测完成，屏蔽项已跳过')}catch(e){flash(e.message,true)}};document.querySelectorAll('[data-monitor]').forEach(row=>{const item=items.find(x=>x.id==row.dataset.monitor),save=async()=>{item.port=Number(row.querySelector('[data-monitor-port]').value);item.note=row.querySelector('[data-monitor-note]').value;item.explicitHidden=(item.filtered||item.domainExcluded)?item.explicitHidden:row.querySelector('[data-monitor-hidden]').checked;item.hidden=item.filtered||item.domainExcluded||item.explicitHidden;try{await api('/api/https-monitors/'+row.dataset.monitor,{method:'PUT',body:JSON.stringify({port:item.port,note:item.note,hidden:item.explicitHidden})});row.classList.toggle('monitor-hidden',item.hidden);row.querySelector('[data-monitor-check]').disabled=item.hidden;flash('监控设置已保存');return true}catch(e){flash(e.message,true);return false}};row.querySelector('[data-monitor-port]').onchange=save;row.querySelector('[data-monitor-note]').onchange=save;row.querySelector('[data-monitor-hidden]').onchange=async()=>{if(await save()&&item.hidden&&!showHiddenMonitors)renderHTTPSMonitors(items)};row.querySelector('[data-monitor-check]').onclick=async e=>{const button=e.currentTarget;button.disabled=true;button.textContent='检测中…';try{const result=await api(`/api/https-monitors/${item.id}/check`,{method:'POST'});Object.assign(item,result);const n=row.querySelector('[data-status]'),t=row.querySelector('[data-checked]'),s=status(item);n.className='monitor-status '+s[0];n.textContent=s[1];n.title=item.lastChecked?`类型：${item.type} / 记录：${item.value}`:'';t.textContent=item.lastChecked?new Date(item.lastChecked).toLocaleString():'—';renderHTTPSMonitors(items);flash(`${item.host} 检测完成`)}catch(err){flash(err.message,true)}finally{button.disabled=item.hidden;button.textContent='监控'}}})}
async function profileView(){const [hint,otps,passkeys]=await Promise.all([passwordPolicy(),api('/api/me/otp'),api('/api/me/passkeys')]);$('#page').innerHTML=`<main><div class="page-heading"><div><span class="eyebrow">个人中心</span><h1>账户设置</h1></div></div><div class="security-grid"><form id="profile" class="settings"><h3>基本资料</h3><label>用户名<input name="username" value="${esc(me.username)}" required></label><label>邮箱<input name="email" type="email" value="${esc(me.email)}" required></label><label>新密码（不修改请留空）<input name="newPassword" type="password"><small>${hint}</small></label><label>再次输入新密码<input name="confirmPassword" type="password"></label><h3>DNS 记录过滤</h3><p class="hint">每行一个关键词，不区分大小写。名称或记录内容包含关键词时，DNS 管理默认隐藏。</p><label>名称过滤项<textarea name="nameFilter" rows="4">${esc(me.nameFilter||'')}</textarea></label><label>记录过滤项<textarea name="valueFilter" rows="4">${esc(me.valueFilter||'')}</textarea></label><div id="notice"></div><button>保存个人设置</button></form><div class="security-column"><section class="security-card"><div class="card-heading"><div><h3>OTP 验证器</h3><p>可注册多个 TOTP 验证器。</p></div><span>${otps.filter(x=>x.enabled).length} 个启用</span></div><form id="otpForm" class="mini-form"><input name="name" placeholder="设备名称，例如：手机" required><button>添加 OTP</button></form><div id="otpSetup"></div><div class="security-list">${otps.map(x=>`<div><span><b>${esc(x.name)}</b><small>${x.enabled?'已启用':'待确认'} · ${esc(x.createdAt)}</small></span><button class="danger" data-otp-delete="${x.id}">删除</button></div>`).join('')||'<p class="empty-note">尚未添加 OTP</p>'}</div></section><section class="security-card"><div class="card-heading"><div><h3>Passkey</h3><p>可注册多个设备或安全密钥。当前绑定域名：<code>${esc(me.passkeyRPID||'localhost')}</code></p></div><span>${passkeys.length} 个</span></div><form id="passkeyForm" class="mini-form"><input name="name" placeholder="名称，例如：Windows Hello" required><button>添加 Passkey</button></form><div class="security-list">${passkeys.map(x=>`<div><span><b>${esc(x.name)}</b><small>${esc(x.createdAt)}</small></span><button class="danger" data-passkey-delete="${x.id}">删除</button></div>`).join('')||'<p class="empty-note">尚未添加 Passkey</p>'}</div></section></div></div></main>`;$('#profile').onsubmit=async e=>{e.preventDefault();try{const result=await api('/api/me/profile/request',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});if(result?.verificationRequired){verificationView()}else{await boot();flash('个人设置已保存')}}catch(x){notice(x.message,true)}};$('#otpForm').onsubmit=addOTP;$('#passkeyForm').onsubmit=addPasskey;document.querySelectorAll('[data-otp-delete]').forEach(x=>x.onclick=()=>ask('确定删除这个 OTP 验证器？',()=>deleteSecurityItem('otp',x.dataset.otpDelete)));document.querySelectorAll('[data-passkey-delete]').forEach(x=>x.onclick=()=>ask('确定删除这个 Passkey？',()=>deleteSecurityItem('passkeys',x.dataset.passkeyDelete)))}
const profileViewBase=profileView;profileView=async function(){await profileViewBase();const email=document.querySelector('#profile input[name="email"]');if(email)email.closest('label').insertAdjacentHTML('afterend',`<h3>HTTPS 监控通知</h3><p class="hint">免检时间只影响后台定时检查，跨午夜时段也支持；手动点击检测仍会执行。</p><div class="quiet-hours"><label>免检开始<input name="httpsQuietStart" type="time" value="${esc(me.httpsQuietStart||'')}"></label><label>免检结束<input name="httpsQuietEnd" type="time" value="${esc(me.httpsQuietEnd||'')}"></label></div><label>每次异常最多通知次数<input name="httpsAlertLimit" type="number" min="1" max="100" value="${me.httpsAlertLimit||1}" required><small>未恢复绿色前，每次检测最多通知到此次数；恢复绿色后自动归零。</small></label><label>Bark Webhook URL<input name="barkURL" type="url" value="${esc(me.barkURL||'')}" placeholder="https://api.day.app/你的Key"></label><label>Bark POST JSON<textarea name="barkBody" rows="6" placeholder='{"title":"{{title}}","body":"{{body}}","group":"DNS Panel"}'>${esc(me.barkBody||'')}</textarea><small>可用变量：{{title}}、{{body}}、{{host}}、{{port}}、{{error}}。留空使用默认 Bark 内容。</small></label><button id="testBark" type="button" class="secondary">测试 Bark 连通</button>`) ;const test=$("#testBark");if(test)test.onclick=async()=>{const form=$("#profile"),url=form.elements.barkURL.value,body=form.elements.barkBody.value;if(!url){flash("请先填写 Bark Webhook URL",true);return}test.disabled=true;test.textContent="正在发送测试…";try{const result=await api("/api/me/bark/test",{method:"POST",body:JSON.stringify({url,body})});flash(result.message||"Bark 测试通知已发送")}catch(e){flash(e.message,true)}finally{test.disabled=false;test.textContent="测试 Bark 连通"}}};
async function addOTP(e){e.preventDefault();try{const x=await api('/api/me/otp',{method:'POST',body:JSON.stringify({name:new FormData(e.target).get('name')})});$('#otpSetup').innerHTML=`<div class="setup-box"><b>请添加到验证器后输入验证码</b><label>密钥<code>${esc(x.secret)}</code></label><label>配置 URI<textarea readonly>${esc(x.uri)}</textarea></label><form id="otpConfirm"><input name="code" inputmode="numeric" maxlength="6" placeholder="6 位验证码" required><button>确认启用</button></form></div>`;$('#otpConfirm').onsubmit=async event=>{event.preventDefault();try{await api(`/api/me/otp/${x.id}/confirm`,{method:'POST',body:JSON.stringify({code:new FormData(event.target).get('code')})});flash('OTP 已启用');profileView()}catch(err){flash(err.message,true)}}}catch(err){flash(err.message,true)}}
const domainManagementViewBase=domainManagementView;
domainManagementView=function(){domainManagementViewBase();const form=$('#domainForm'),table=$('.domain-table');if(form){const noticeBox=$('#notice'),noteLabel=document.createElement('label');noteLabel.innerHTML='备注<input name="note" maxlength="500" placeholder="例如：官网、邮件、测试环境">';form.insertBefore(noteLabel,noticeBox)}if(!table)return;table.insertAdjacentHTML('beforebegin',`<label class="table-search"><span>检索域名</span><input id="domainSearch" type="search" value="${esc(domainSearch)}" placeholder="输入域名、厂商、API Key、Zone ID 或备注"></label>`);const head=table.querySelector('.domain-row.head'),headCells=[...head.children];headCells[4].textContent='备注';head.insertAdjacentHTML('afterbegin','<span class="drag-column" title="拖动排序">⠿</span>');document.querySelectorAll('[data-domain-drag]').forEach(row=>{const item=domains.find(x=>x.id==row.dataset.domainDrag),handle=row.querySelector('.managed-drag-handle'),remove=row.querySelector('[data-domain]'),note=document.createElement('input');row.draggable=false;handle.draggable=true;handle.textContent='⠿';handle.title='按住拖动调整顺序';handle.setAttribute('aria-label','拖动排序');row.insertBefore(handle,row.firstChild);note.className='domain-note';note.value=item?.note||'';note.placeholder='填写用途备注';note.maxLength=500;note.onchange=async()=>{try{await api('/api/domains/'+item.id,{method:'PUT',body:JSON.stringify({note:note.value})});item.note=note.value;flash('域名备注已保存')}catch(e){flash(e.message,true)}};row.insertBefore(note,remove)});const search=$('#domainSearch'),filter=()=>{domainSearch=search.value;const term=domainSearch.trim().toLowerCase();document.querySelectorAll('[data-domain-drag]').forEach(row=>{const item=domains.find(x=>x.id==row.dataset.domainDrag),values=[item?.name,item?.provider,item?.credential,item?.zoneId,item?.note].join(' ').toLowerCase(),match=term===''||values.includes(term);row.hidden=!match;row.style.display=match?'':'none'})};search.oninput=filter;filter()};
const keyViewBase=keyView;
keyView=function(){keyViewBase();const table=$('.credential-table');if(!table)return;const head=table.querySelector('.credential-row.head'),dragHeading=head.children[4];dragHeading.remove();head.insertAdjacentHTML('afterbegin','<span class="drag-column" title="拖动排序">⠿</span>');document.querySelectorAll('[data-key-drag]').forEach(row=>{const handle=row.querySelector('.managed-drag-handle');row.draggable=false;handle.draggable=true;handle.textContent='⠿';handle.title='按住拖动调整顺序';handle.setAttribute('aria-label','拖动排序');row.insertBefore(handle,row.firstChild)})};
const renderHTTPSMonitorsBase=renderHTTPSMonitors;
renderHTTPSMonitors=function(items){renderHTTPSMonitorsBase(items);const toolbar=$('.monitor-toolbar');if(!toolbar)return;toolbar.insertAdjacentHTML('beforebegin',`<label class="table-search"><span>检索 HTTPS</span><input id="httpsSearch" type="search" value="${esc(httpsSearch)}" placeholder="输入主机名、备注、状态或证书信息"></label>`);const search=$('#httpsSearch'),filter=()=>{httpsSearch=search.value;const term=httpsSearch.trim().toLowerCase();let shown=0;document.querySelectorAll('.monitor-row:not(.head)').forEach(row=>{const item=items.find(x=>x.id==row.dataset.monitor),values=[item?.host,item?.type,item?.value,item?.note,item?.error,item?.certificateDomains,item?.daysRemaining,item?.lastChecked,item?.valid?'有效':'失败'].join(' ').toLowerCase(),match=term===''||values.includes(term);row.hidden=!match;row.style.display=match?'':'none';if(match)shown++});const count=$('.monitor-count b');if(count)count.textContent=shown};search.oninput=filter;filter()};
const userManagementViewBase=userManagementView;
userManagementView=async function(page=1){await userManagementViewBase(page);const table=$('.user-table');if(!table)return;table.insertAdjacentHTML('beforebegin',`<label class="table-search"><span>检索用户</span><input id="userSearch" type="search" value="${esc(userSearch)}" placeholder="输入用户名、邮箱或角色"></label>`);const search=$('#userSearch');search.oninput=()=>{userSearch=search.value;const term=userSearch.trim().toLowerCase();document.querySelectorAll('.user-row:not(.head)').forEach(row=>{const match=term===''||row.textContent.toLowerCase().includes(term);row.hidden=!match;row.style.display=match?'':'none'});clearTimeout(userManagementView.searchTimer);userManagementView.searchTimer=setTimeout(()=>userManagementView(1),300)};search.focus();search.setSelectionRange(search.value.length,search.value.length)};
const fromB64=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((s.length+3)%4)),c=>c.charCodeAt(0));const toB64=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
async function addPasskey(e){e.preventDefault();if(!window.PublicKeyCredential){flash('当前浏览器不支持 Passkey',true);return}try{const start=await api('/api/me/passkeys/begin',{method:'POST',body:JSON.stringify({name:new FormData(e.target).get('name')})}),options=start.options.publicKey;options.challenge=fromB64(options.challenge);options.user.id=fromB64(options.user.id);if(options.excludeCredentials)options.excludeCredentials.forEach(x=>x.id=fromB64(x.id));const credential=await navigator.credentials.create({publicKey:options}),body={id:credential.id,rawId:toB64(credential.rawId),type:credential.type,response:{clientDataJSON:toB64(credential.response.clientDataJSON),attestationObject:toB64(credential.response.attestationObject),transports:credential.response.getTransports?credential.response.getTransports():[]},clientExtensionResults:credential.getClientExtensionResults(),authenticatorAttachment:credential.authenticatorAttachment};await api('/api/me/passkeys/finish?token='+encodeURIComponent(start.sessionToken),{method:'POST',body:JSON.stringify(body)});flash('Passkey 已添加');profileView()}catch(err){flash('Passkey 添加失败：'+err.message,true)}}
async function deleteSecurityItem(kind,id){try{await api(`/api/me/${kind}/${id}`,{method:'DELETE'});flash('安全凭据已删除');profileView()}catch(e){flash(e.message,true)}}
function verificationView(){$('#page').innerHTML=`<main><form id="verify" class="settings"><h2>验证邮箱</h2><p>验证码已经发送至新邮箱，10 分钟内有效。</p><label>6 位验证码<input name="code" inputmode="numeric" maxlength="6" required></label><div id="notice"></div><button>确认修改</button></form></main>`;$('#verify').onsubmit=async e=>{e.preventDefault();try{await api('/api/me/profile/confirm',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await boot()}catch(x){notice(x.message,true)}}}
async function settingsView(){const s=await api('/api/settings');let defaults=[];try{defaults=JSON.parse(s.default_record_types)}catch{};const security=[['registration_enabled','开放注册'],['email_verification','注册及邮箱修改需要验证码'],['require_mfa','强制二次认证'],['login_notification','登录通知邮件']];const rules=[['password_require_number','密码需要数字'],['password_require_uppercase','密码需要大写字母'],['password_require_lowercase','密码需要小写字母'],['password_require_symbol','密码需要符号']];const recordTypes=['A','AAAA','CNAME','TXT','MX','CAA','SRV'];$('#page').innerHTML=`<main><h1>全局设置</h1><form id="settings" class="settings"><h3>用户与安全</h3>${security.map(([k,l])=>`<label class="toggle"><input name="${k}" type="checkbox" ${s[k]==='true'?'checked':''}>${l}</label>`).join('')}<small>强制二次认证要求 SMTP 已通过连接测试。普通用户可选择 OTP、Passkey 或邮箱验证码。</small><h3>Passkey 域名</h3><p class="hint">RP ID 通常填写网站域名，不含协议和端口。Origin 填写完整来源；多个来源用英文逗号分隔。修改后已有 Passkey 通常需要重新注册。</p><label>Passkey RP ID<input name="passkey_rp_id" value="${esc(s.passkey_rp_id||'')}" placeholder="panel.example.com"></label><label>允许的 Origin<input name="passkey_origins" value="${esc(s.passkey_origins||'')}" placeholder="https://panel.example.com"></label><h3>密码规则</h3><p class="hint">长度设置为 0 表示不限制。</p><label>密码最小长度<input name="password_min_length" type="number" min="0" max="128" value="${esc(s.password_min_length||'0')}" required></label>${rules.map(([k,l])=>`<label class="toggle"><input name="${k}" type="checkbox" ${s[k]==='true'?'checked':''}>${l}</label>`).join('')}<h3>DNS 默认显示</h3><div class="setting-checks">${recordTypes.map(t=>`<label><input data-default-record type="checkbox" value="${t}" ${defaults.includes(t)?'checked':''}>${t}</label>`).join('')}</div><h3>页面通知</h3><label>通知显示时间<select name="notification_duration"><option value="3" ${s.notification_duration==='3'?'selected':''}>3 秒</option><option value="5" ${s.notification_duration==='5'?'selected':''}>5 秒</option><option value="manual" ${s.notification_duration==='manual'?'selected':''}>手动关闭</option></select></label><h3>SMTP</h3>${[['smtp_host','服务器'],['smtp_port','端口'],['smtp_username','用户名'],['smtp_password','密码'],['smtp_from','发件地址']].map(([k,l])=>`<label>${l}<input name="${k}" ${k==='smtp_password'?'type="password"':''} value="${esc(s[k])}"></label>`).join('')}<div id="notice"></div><div class="form-actions"><button>保存设置</button><button id="testSMTP" type="button" class="secondary">测试连接</button><button id="testEmail" type="button" class="secondary">发送测试邮件</button></div></form></main>`;$('#testSMTP').onclick=async()=>{try{await api('/api/settings/test-smtp',{method:'POST'});flash('SMTP 连接和认证测试成功')}catch(x){flash(x.message,true)}};$('#testEmail').onclick=async()=>{try{const x=await api('/api/settings/test-email',{method:'POST'});flash('测试邮件已发送至 '+x.sentTo)}catch(x){flash(x.message,true)}};const submit=async form=>{const v={};for(const x of form.elements)if(x.name)v[x.name]=x.type==='checkbox'?String(x.checked):x.value;v.default_record_types=JSON.stringify([...document.querySelectorAll('[data-default-record]:checked')].map(x=>x.value));try{await api('/api/settings',{method:'PUT',body:JSON.stringify(v)});notificationDuration=v.notification_duration;types=JSON.parse(v.default_record_types);flash('设置已保存')}catch(x){notice(x.message,true)}};$('#settings').onsubmit=e=>{e.preventDefault();const enabling=s.require_mfa!=='true'&&e.target.elements.require_mfa.checked;if(enabling)ask('启用后，所有普通用户下次登录必须使用 OTP、Passkey 或邮箱验证码。确认启用？',()=>submit(e.target));else submit(e.target)}}
const settingsViewBase=settingsView;
settingsView=async function(){await settingsViewBase();const form=$('#settings');form.insertAdjacentHTML('afterbegin',`<h3>站点地址</h3><p class="hint">密码重置链接和 Passkey 域名都从这里取得。请填写浏览器实际访问的完整地址，不要包含路径，例如 https://dns.example.com。修改域名后，已有 Passkey 通常需要重新注册。</p><label>站点 URL<input name="site_url" type="url" value="${esc((await api('/api/settings')).site_url||'')}" placeholder="https://dns.example.com"></label>`)};
const profileBackupViewBase=profileView;
profileView=async function(){currentView='profile';updateHeaderSearch();await profileBackupViewBase();const column=$('.security-column');if(!column)return;column.insertAdjacentHTML('beforeend',`<section class="security-card backup-card"><div class="card-heading"><div><h3>加密导入与导出</h3><p>${me.role==='admin'?'导出 API、域名、个人设置和全部全局设置。':'导出 API、域名和个人设置。'}认证密码、OTP 和 Passkey 不会导出。</p></div><span>AES-256-GCM</span></div><form id="backupExport" class="backup-form"><label>导出密码<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><label>再次输入密码<input name="confirm" type="password" minlength="8" autocomplete="new-password" required></label><button>导出加密 JSON</button></form><form id="backupImport" class="backup-form"><label>选择备份文件<input name="file" type="file" accept="application/json,.json" required></label><label>解密密码<input name="password" type="password" minlength="8" autocomplete="current-password" required></label><button class="secondary">导入并合并数据</button></form><p class="hint">请妥善保存密码。密码遗失后无法恢复备份；导入会更新同名配置并保留其他现有数据。</p></section>`);$('#backupExport').onsubmit=exportEncryptedBackup;$('#backupImport').onsubmit=importEncryptedBackup};
async function exportEncryptedBackup(e){e.preventDefault();const form=e.currentTarget,password=form.elements.password.value;if(password!==form.elements.confirm.value){flash('两次输入的导出密码不一致',true);return}const button=form.querySelector('button');button.disabled=true;try{const data=await api('/api/me/backup/export',{method:'POST',body:JSON.stringify({password})}),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`dns-panel-backup-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);form.reset();flash('加密备份已导出，请同时妥善保存密码')}catch(err){flash(err.message,true)}finally{button.disabled=false}}
async function importEncryptedBackup(e){e.preventDefault();const form=e.currentTarget,file=form.elements.file.files[0],password=form.elements.password.value;if(!file)return;const button=form.querySelector('button');button.disabled=true;try{if(file.size>10*1024*1024)throw Error('备份文件不能超过 10 MB');const data=JSON.parse(await file.text()),result=await api('/api/me/backup/import',{method:'POST',body:JSON.stringify({password,data})});form.reset();await boot();await profileView();flash(`导入完成：${result.credentials} 个 API Key，${result.domains} 个域名`)}catch(err){flash(err instanceof SyntaxError?'备份文件不是有效 JSON':err.message,true)}finally{button.disabled=false}}
const initialResetToken=new URLSearchParams(location.search).get('reset');if(initialResetToken)resetPasswordView(initialResetToken);else boot();
